head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "uldmgt60101";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.form_listForm = { action: "", method: 'post', target: '' };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'uldmgt60101.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name form_13_onsubmit
 * @description form_13 onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.form_13_onsubmit = function(e){
    try {
        return false

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt60101.form_13_onsubmit' }); }
};

/**
 * @method
 * @name rd_market_onclick
 * @description rd_market 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.rd_market_onclick = async function(e){
    try {
        await scwin.list()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt60101.rd_market_onclick' }); }
};

/**
 * @method
 * @name img_62_onclick
 * @description img_62 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_62_onclick = async function(e){
    try {
        await scwin.popInsert()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt60101.img_62_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_PopInsert
 * @description Pop Insert 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_PopInsert = async function () {
    const sbmOptions = {
        id: "tx_fn_PopInsert",
        method: "post",
        action: "/filing/popupManage.do",
        ref: "dma_PopInsertReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_PopModify
 * @description Pop Modify 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_PopModify = async function () {
    const sbmOptions = {
        id: "tx_fn_PopModify",
        method: "post",
        action: "/filing/popupManage.do",
        ref: "dma_PopModifyReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_Delete
 * @description Delete 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Delete = async function () {
    const sbmOptions = {
        id: "tx_fn_Delete",
        method: "post",
        action: "/filing/popupManage.do",
        ref: "dma_DeleteReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_List_xhr
 * @description List xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_List_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_List_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_List_xhr", unresolved: "action:self_submit:tx_fn_List_xhr" };
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name list
 * @description list 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.list = async function () {
    scwin.form_listForm.action = "/filing/popupManage.do";
    $c.util.getComponent('dma_PopInsertReq').set('method', "popupList");
    await scwin.tx_fn_List_xhr();
};

/**
 * @method
 * @name onCompleteResponse
 * @description on Complete Response 처리
 * @param {*} responseText responseText
 * @returns {void}
 * @hidden N
 */
scwin.onCompleteResponse = function (responseText) {
    $c.util.getComponent('txt_listDiv').setValue(responseText);
};

/**
 * @method
 * @name popInsert
 * @description pop Insert 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.popInsert = async function () {
    $c.util.getComponent('dma_PopInsertReq').set('method', "popupManageInsert");
    $c.util.getComponent('dma_PopInsertReq').set('mode', "insert");
    await scwin.tx_fn_PopInsert();
};

/**
 * @method
 * @name popModify
 * @description pop Modify 처리
 * @param {*} key key
 * @param {*} description description
 * @param {String} width width
 * @param {String} height height
 * @param {*} name name
 * @param {*} from from
 * @param {*} to to
 * @param {*} rd_market rd_market
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.popModify = async function (key, description, width, height, name, from, to, rd_market) {
    $c.util.getComponent('dma_PopInsertReq').set('method', "popupManageInsert");
    $c.util.getComponent('dma_PopInsertReq').set('mode', "modify");
    $c.util.getComponent('dma_PopInsertReq').set('key', key);
    $c.util.getComponent('dma_PopInsertReq').set('description', encodeURI(description));
    $c.util.getComponent('dma_PopInsertReq').set('width', width);
    $c.util.getComponent('dma_PopInsertReq').set('height', height);
    $c.util.getComponent('dma_PopInsertReq').set('name', encodeURI(name));
    $c.util.getComponent('dma_PopInsertReq').set('from', from);
    $c.util.getComponent('dma_PopInsertReq').set('to', to);
    $c.util.getComponent("rd_market").setValue(rd_market);
    await scwin.tx_fn_PopModify();
};

/**
 * @method
 * @name deletePopInsertReq
 * @description delete Pop Insert Req 처리
 * @param {*} key key
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.deletePopInsertReq = async function (key) {
    $c.util.getComponent('dma_PopInsertReq').set('method', "popupDelete");
    $c.util.getComponent('dma_PopInsertReq').set('mode', "delete");
    $c.util.getComponent('dma_PopInsertReq').set('key', key);
    await scwin.tx_fn_Delete();
};

/**
 * @method
 * @name onEnter
 * @description on Enter 처리
 * @returns {void}
 * @hidden N
 */
scwin.onEnter = function () {
    if (event.keyCode === 13) {
        fn_Search();  // TODO Stage2(pcc 반입 2차): as-is 공통 fn_Search — as-is 정의 없음(원본 JS 미제공 — 회신)
    }
};
